from __future__ import annotations

from pydantic import Field
from typing_extensions import TypedDict

from ..core import SdkBaseModel


class DbtCloud(SdkBaseModel):
    dbt_unique_id: str = Field(alias="dbtUniqueId")
    """Unique ID of the model assigned by dbt (usually some combination of the schema and table name)"""

    compiled_sql: str = Field(alias="compiledSql")
    """Compiled SQL in the dbt model"""

    raw_sql: str = Field(alias="rawSql")
    name: str
    """Name of the table generated by the dbt model"""

    model_id: float = Field(alias="modelId")
    """Model id that refer to a dbt model"""


class DbtCloudDict(TypedDict):
    dbt_unique_id: str
    compiled_sql: str
    raw_sql: str
    name: str
    model_id: float
